"""Read-only PSOP HTTPS and exact Pages identity observation; no mutation API."""
import pathlib
import re
import ssl
import subprocess
import time
import urllib.parse
import urllib.request

from psop_client import member
from v3_backend_trust import digest, strict_json, require_test_root
from v3_promotion_planner import PlanningError
from v3_branch_pages import BranchPagesIdentity
from v3_github_provider import GitHubStorage
from v3_provider_transport import ProviderTransport


class ExternalScope:
    """Operator-provided read authorization inventory, never generated by tests.

    Human authorization is an out-of-band prerequisite, not established by this
    JSON parser. Even with this inventory, the adapter exposes GETs only.
    """
    def __init__(self, value, *, now):
        keys = {"repository", "repository_id", "node_id", "branch", "origin", "operator", "authorized_until", "purpose"}
        if (not isinstance(value, dict) or set(value) != keys or value["purpose"] != "read-only-psop-disposable-acceptance"
                or not isinstance(value["operator"], str) or not value["operator"].strip()
                or type(value["authorized_until"]) is not int or not now < value["authorized_until"] <= now + 86400
                or not re.fullmatch(r"[A-Za-z0-9-]+/ro-psop-disposable-[a-z0-9-]+", value["repository"])
                or type(value["repository_id"]) is not int or value["repository_id"] < 1 or value["repository_id"] == 1159460821
                or not re.fullmatch(r"psop-disposable-[a-z0-9-]+", value["branch"])
                or not isinstance(value["node_id"], str) or not value["node_id"]):
            raise PlanningError("explicit independent disposable Pages authorization inventory required")
        owner, repo = value["repository"].split("/")
        if value["origin"] != "https://" + owner.lower() + ".github.io/" + repo:
            raise PlanningError("exact isolated GitHub Pages project origin required")
        self.value = dict(value)


def checked_origin(origin, *, scope=None):
    if not isinstance(origin, str) or any(c.isspace() for c in origin):
        raise PlanningError("invalid HTTPS origin")
    p = urllib.parse.urlsplit(origin)
    if scope is not None:
        if not isinstance(scope, ExternalScope) or origin != scope.value["origin"]:
            raise PlanningError("origin differs from operator-authorized test project")
    elif (p.scheme != "https" or p.hostname not in {"localhost", "127.0.0.1"} or p.port is None
            or not 1024 <= p.port <= 65535 or p.path or p.username or p.password or p.query or p.fragment
            or origin != "https://" + p.hostname + ":" + str(p.port)):
        raise PlanningError("only explicit loopback HTTPS or separately authorized disposable Pages origin allowed")
    return origin


class HTTPSReader:
    def __init__(self, origin, result, attempt, *, ca=None, scope=None, max_bytes=256 * 1024 * 1024):
        self.origin = checked_origin(origin, scope=scope)
        if not re.fullmatch(r"[a-f0-9]{64}", result) or not re.fullmatch(r"[A-Za-z0-9_-]{1,128}", attempt):
            raise PlanningError("exact PSOP immutable result/attempt required")
        self.base = self.origin + "/psop/snapshots/" + result + "/"
        self.publication_url = self.origin + "/psop/publications/" + attempt + ".json"
        self.max_bytes = max_bytes
        self.tls = ssl.create_default_context(cafile=None if ca is None else ca["path"])

    def get(self, url):
        if not url.startswith(self.origin + "/"):
            raise PlanningError("cross-origin HTTPS rejected")
        class NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *args, **kwargs):
                raise PlanningError("HTTPS redirect rejected")
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}), NoRedirect(), urllib.request.HTTPSHandler(context=self.tls))
        request = urllib.request.Request(url, headers={"Cache-Control": "no-cache"})
        with opener.open(request, timeout=30) as response:
            raw = response.read(self.max_bytes + 1)
        if len(raw) > self.max_bytes:
            raise PlanningError("HTTPS member exceeds size bound")
        return raw

    def read(self, path):
        return self.get(self.base + urllib.parse.quote(member(path), safe="/"))

    def publication(self):
        return self.get(self.publication_url)


class GHRead(ProviderTransport):
    def __init__(self, scope):
        super().__init__("https://api.github.com", lambda: None, time.time)
        self.scope = scope
        self.base = "/repos/" + scope.value["repository"]
        self.observations = {}

    def request(self, method, path, body=None, *, allow_list=False):
        suffix = path[len(self.base):] if path.startswith(self.base) else None
        allowed = (suffix == "" or suffix == "/pages" or suffix is not None and any(re.fullmatch(pattern, suffix) for pattern in (
            r"/git/ref/heads/psop-disposable-[a-z0-9-]+", r"/git/commits/[a-f0-9]{40}",
            r"/git/trees/[a-f0-9]{40}\?recursive=1", r"/git/blobs/[a-f0-9]{40}",
            r"/pages/builds/[1-9][0-9]*", r"/deployments/[1-9][0-9]*",
            r"/deployments/[1-9][0-9]*/statuses\?per_page=1", r"/actions/runs/[1-9][0-9]*")))
        if method != "GET" or body is not None or not allowed or time.time() >= self.scope.value["authorized_until"]:
            raise PlanningError("read-only Pages exact GET allowlist or authorization expired")
        result = subprocess.run(["gh", "api", "--method", "GET", path.lstrip("/")], capture_output=True, timeout=60)
        if result.returncode:
            raise PlanningError("read-only GitHub observation unavailable; UNVERIFIED")
        value = strict_json(result.stdout)
        self.observations[path] = digest(result.stdout)
        return value


def verify_external(scope, client, descriptor, *, commit, build_id, deployment_id, run_id):
    """No repo/Pages setup or push; complete-byte check bracketed by exact facts."""
    if not isinstance(scope, ExternalScope) or client.scope is not scope:
        raise PlanningError("explicit external disposable read authorization required")
    require_test_root(client.root)
    t = GHRead(scope);v = scope.value
    storage = GitHubStorage(t, repository=v["repository"], repository_id=v["repository_id"], node_id=v["node_id"], ref="refs/heads/" + v["branch"])
    metadata = t.request("GET", storage.base)
    if metadata.get("description") != "RO PSOP DISPOSABLE ACCEPTANCE ONLY":
        raise PlanningError("independent disposable repository marker missing")
    identity = BranchPagesIdentity(storage, branch=v["branch"])
    facts = identity.identify(commit, build_id=build_id, deployment_id=deployment_id, run_id=run_id)
    d = strict_json(descriptor)["payload"]
    if d["receipt"]["target_git"] != commit:
        raise PlanningError("public receipt/expected Git commit substitution")
    files = storage.files(commit)
    view = client.verify(descriptor)
    try:
        prefix = "psop/snapshots/" + d["result_sha256"] + "/"
        for item in d["signed_inventory"]:
            path = prefix + item["path"]
            if path not in files or digest(storage.blob(files[path])) != item["sha256"]:
                raise PlanningError("public complete payload differs from exact Git tree")
        pub = "psop/publications/" + d["receipt"]["attempt"] + ".json"
        if pub not in files or digest(storage.blob(files[pub])) != d["publication_sha256"]:
            raise PlanningError("publication differs from exact Git tree")
        identity.identify(commit, build_id=build_id, deployment_id=deployment_id, run_id=run_id)
        return {"scope": "external-disposable-read-only-observation", "status": "PASS_OBSERVATION", "provider": facts,
            "descriptor_sha256": digest(descriptor), "inventory_paths": len(view.inventory), "observed_at": int(client.clock()),
            "api_response_sha256": t.observations, "coverage": "all-signed-paths-at-one-observation-point",
            "global_latest": "UNVERIFIED", "global_cdn_freshness": "UNVERIFIED", "pages_build_ordering": "UNVERIFIED",
            "provider_deadline_fencing": "UNVERIFIED", "production_activation": "BLOCKED", "publishable": False}
    finally:
        import shutil
        shutil.rmtree(view.path)
